import Cocoa

/// ⌘C 兜底取词用的剪贴板快照。
///
/// - 只有真的要模拟 ⌘C 时才拍快照；
/// - 只保存已经物化的数据：跳过「用到时才生成」的类型（文件承诺、动态类型），
///   累计超过 20MB（大图片）就放弃快照——这种情况调用方应放弃 ⌘C 兜底，只记 changeCount；
/// - 还原写回时加上 `org.nspasteboard.TransientType` 和 `org.nspasteboard.AutoGeneratedType`，
///   让 Paste、Maccy 这类剪贴板管理器跳过这次写入，不会多出重复条目。
///
/// 参考：Decklet `decklet-sys/src/pasteboard.rs`。
public struct PasteboardSnapshot {
    public static let transientType = NSPasteboard.PasteboardType("org.nspasteboard.TransientType")
    public static let autoGeneratedType = NSPasteboard.PasteboardType("org.nspasteboard.AutoGeneratedType")
    public static let concealedType = NSPasteboard.PasteboardType("org.nspasteboard.ConcealedType")
    public static let maxBytes = 20 << 20

    /// 每个 item 一组 (type, data)
    public let items: [[(NSPasteboard.PasteboardType, Data)]]
    /// 拍快照时的 changeCount
    public let changeCount: Int

    /// 不能物化的类型：读它会触发源 App 现场生成（文件承诺等），既慢又可能抛异常
    public static func isLazyType(_ t: NSPasteboard.PasteboardType) -> Bool {
        let r = t.rawValue
        if r.hasPrefix("dyn.") { return true }
        return [
            "com.apple.pasteboard.promised-file-url",
            "com.apple.pasteboard.promised-file-content-type",
            "com.apple.NSFilePromiseItemMetaData",
            "NSPromiseContentsPboardType",
            "com.apple.pasteboard.promised-suggested-file-name",
        ].contains(r)
    }

    /// 拍快照；内容过大返回 nil（调用方应放弃 ⌘C 兜底）
    public static func take(_ pb: NSPasteboard = .general) -> PasteboardSnapshot? {
        var out: [[(NSPasteboard.PasteboardType, Data)]] = []
        var total = 0
        for item in pb.pasteboardItems ?? [] {
            var v: [(NSPasteboard.PasteboardType, Data)] = []
            for t in item.types where !isLazyType(t) {
                guard let d = item.data(forType: t) else { continue }
                total += d.count
                if total > maxBytes { return nil }
                v.append((t, d))
            }
            out.append(v)
        }
        return PasteboardSnapshot(items: out, changeCount: pb.changeCount)
    }

    /// 写回快照并打上临时标记；返回写回后的 changeCount
    @discardableResult
    public func restore(to pb: NSPasteboard = .general) -> Int {
        pb.clearContents()
        let objs = items.filter { !$0.isEmpty }.map { pairs -> NSPasteboardItem in
            let it = NSPasteboardItem()
            for (t, d) in pairs { it.setData(d, forType: t) }
            it.setData(Data(), forType: Self.transientType)
            it.setData(Data(), forType: Self.autoGeneratedType)
            return it
        }
        if !objs.isEmpty { pb.writeObjects(objs) }
        return pb.changeCount
    }

    /// 当前剪贴板内容是否不该进历史（密码管理器、临时写入）
    public static func shouldSkipForHistory(_ pb: NSPasteboard = .general) -> Bool {
        let types = Set(pb.types ?? [])
        return types.contains(concealedType) || types.contains(transientType) || types.contains(autoGeneratedType)
    }
}
